# frozen_string_literal: true

require 'fileutils'
require 'minitest/autorun'
require 'open3'
require 'tmpdir'
require_relative '../../tools/lib/erx/oracle'
require_relative '../../tools/lib/erx/runtime'

# public_key's generated sources: the import carries none of them, and the runtime
# build generates them on the host, the ASN.1 compiler from lib/public_key/asn1 and
# convert.escript from priv/moduli. Two fresh copies of the application at paths of
# different depth are generated by OTP's own makefiles, with the stock oracle's erlc
# and its configured tree as ERL_TOP and the variables Erx::Runtime gives public_key's
# make. Each generated source and each beam must be byte-identical in both, so no
# checkout's path reaches a module, and none of them may be in the import. Without
# ERL_DETERMINISTIC=yes the ASN.1 compiler writes the directory it ran in (its cwd
# option) into each module, and the copies differ.
class PublicKeyGenerationTest < Minitest::Test
  ROOT = File.expand_path('../..', __dir__)
  APPLICATION = File.join(ROOT, 'otp/lib/public_key')
  FLAVOUR = Erx::Runtime::HOST_OTP_FLAVOUR
  # What each copy starts with: the specifications, the hand-written headers, the
  # moduli list and its converter, and the version the makefiles include.
  INPUTS = %w[asn1 include priv vsn.mk].freeze
  # Where the makefiles write what they generate and compile.
  OUTPUTS = %w[src include ebin].freeze
  # The ASN.1 compiler's own record of the types of each specification it compiled,
  # which it reads when another specification imports them. It holds terms of the
  # compiler's own tables, which differ from run to run; nothing compiles from it
  # once the modules are generated, and no release ships it.
  TYPE_DATABASE = /\.asn1db\z/
  DEADLINE = 600

  def setup
    oracle = Erx::Oracle.new(root: ROOT)
    @erl_top = oracle.source_path(FLAVOUR)
    @bin = File.dirname(oracle.erl_path(FLAVOUR))
    targets = Dir.glob('make/*/otp.mk', base: @erl_top).map { |path| File.basename(File.dirname(path)) }
    assert_equal 1, targets.size, "the oracle's configured tree names one target: #{targets}"
    @target = targets.first
    @scratch = File.realpath(Dir.mktmpdir('erx-public-key-'))
  end

  def teardown
    FileUtils.rm_rf(@scratch) if @scratch
  end

  def test_two_copies_generate_the_same_bytes
    # The two copies generate at once, each by its own make, to halve the wait.
    first, second = %w[a another/checkout].map { |path| Thread.new { generate(File.join(@scratch, path, 'lib/public_key')) } }
                                          .map(&:value)
    assert_operator first.keys.grep(/\Asrc\/.*\.erl\z/).size, :>, 1, 'the ASN.1 compiler generated no module'
    assert_includes first.keys, 'src/pubkey_moduli.hrl'
    assert_includes first.keys, 'include/PKCS-FRAME.hrl'
    assert_equal first.keys.sort, second.keys.sort
    differing = first.keys.grep_v(TYPE_DATABASE).reject { |path| first.fetch(path) == second.fetch(path) }
    assert_empty differing, 'generated files differ between two copies'
    sources = first.keys.reject { |path| path.start_with?('ebin/') }
    assert_empty sources.select { |path| File.exist?(File.join(APPLICATION, path)) }, 'the import carries a generated file'
  end

  private

  # A fresh copy at directory, generated by the asn1 make's opt target and the src
  # make's moduli rule; returns each generated file's bytes by its path in the copy.
  def generate(directory)
    FileUtils.mkdir_p([File.join(directory, 'src'), File.join(directory, 'ebin')])
    INPUTS.each { |input| FileUtils.cp_r(File.join(APPLICATION, input), directory) }
    FileUtils.cp(File.join(APPLICATION, 'src/Makefile'), File.join(directory, 'src'))
    before = files(directory)
    make(directory, 'asn1', 'opt')
    make(directory, 'src', 'pubkey_moduli.hrl')
    files(directory).reject { |path, bytes| before[path] == bytes }
  end

  def make(directory, subdirectory, target)
    argv = ['gtimeout', '-k', '10', DEADLINE.to_s, 'gmake', '-C', File.join(directory, subdirectory), target,
            "TARGET=#{@target}", *Erx::Runtime::MAKE_VARIABLES.fetch('public_key')]
    env = Erx::Oracle::CLEAN_ERLANG_ENV.merge('ERL_TOP' => @erl_top, 'ERL_COMPILE_FLAGS' => '+deterministic',
                                              'PATH' => [@bin, ENV.fetch('PATH')].join(File::PATH_SEPARATOR))
    output, status = Open3.capture2e(env, *argv, in: File::NULL)
    assert status.success?, "#{argv.join(' ')} failed:\n#{output}"
  end

  def files(directory)
    OUTPUTS.flat_map { |output| Dir.glob("#{output}/*", base: directory) }
           .select { |path| File.file?(File.join(directory, path)) }
           .to_h { |path| [path, File.binread(File.join(directory, path))] }
  end
end
